insert into public.blogs (id, titulo, resumen, imagen, contenido, fuente_nombre, fuente_url) values
('rtx-5090-desaparece-precios-10000', 'La NVIDIA GeForce RTX 5090 desaparece de las tiendas: los precios se acercan a $10.000', 'El precio recomendado de la RTX 5090 era $1999, pero la escasez y la especulación han disparado su valor en EE.UU. y Europa a cifras estratosféricas.', '/img/rtx.jpg', ARRAY['El precio recomendado de la GeForce RTX 5090 al lanzamiento era $1999. Sin embargo, la situación actual en los minoristas es muy diferente. Newegg ofrece directamente solo dos conjuntos ASUS 20.º Anniversary.','Las tarjetas gráficas individuales en el marketplace de Newegg son vendidas por terceros a precios exorbitantes. Una MSI Ventus se cotiza muy por encima de su valor original.','En Micro Center la situación es un poco mejor: algunas versiones aún están disponibles, pero el stock depende de la tienda específica y solo se puede retirar en persona.','En Europa, la situación tampoco se asemeja a los precios recomendados. El sitio alemán Geizhals mostraba ofertas muy por encima del precio original de lanzamiento.','Una de las causas de la reducción de los inventarios minoristas podría ser la demanda de empresas que desarrollan sistemas de inteligencia artificial.','NVIDIA no ha anunciado el cese de producción de GeForce RTX 5090, pero la disponibilidad del buque insignia en el comercio minorista habitual ha disminuido notablemente.']::text[], NULL, NULL),
('zelda-ocarina-remake-switch-2', 'Zelda: Ocarina of Time apunta a 1080p y 60 FPS en Switch 2', 'El esperado remake del clásico de Nintendo 64 para Switch 2 funcionará a 1080p y 60 FPS según Digital Foundry. Su lanzamiento está fijado para noviembre de 2026.', '/img/bogs2.webp', ARRAY['El regreso de Zelda: Ocarina of Time comienza a tomar forma mientras se acerca el lanzamiento de su remake para Nintendo Switch 2.','De acuerdo con un análisis técnico realizado por Digital Foundry, el remake funciona a una resolución de 1080p y mantiene los 60 FPS.','El análisis también señala que el remake no utiliza DLSS para realizar el reescalado, uno de los puntos más destacados de las pruebas.','El remake de The Legend of Zelda: Ocarina of Time llegará a Nintendo Switch 2 el próximo 5 de noviembre de 2026.']::text[], NULL, NULL),
('dlss5', 'DLSS 5 y la polémica del "efecto película"', 'NVIDIA desató un intenso debate al prometer transformar los videojuegos en producciones cinematográficas. Probamos la tecnología en NBA 2K27 y te contamos por qué la realidad es mucho más sutil de lo que parece.', '/img/blog.jpg', ARRAY['El anuncio de DLSS 5 generó revuelo apenas NVIDIA lo presentó como un salto hacia un ''efecto película'' dentro de los videojuegos, prometiendo cuadros generados con una suavidad y una iluminación mucho más cercanas a una producción cinematográfica que a un render en tiempo real.','En la práctica, la diferencia es perceptible sobre todo en escenas cinemáticas y en títulos deportivos como NBA 2K27, donde la generación de cuadros intermedios suaviza el movimiento de cámara. Sin embargo, en jugabilidad activa y con movimientos rápidos, los usuarios reportan que el efecto es mucho más discreto de lo que sugería el marketing inicial.','La recomendación general para quienes actualicen su tarjeta gráfica pensando en esta tecnología es probarla directamente en el título que más juegan antes de basar la decisión de compra únicamente en las demostraciones oficiales.']::text[], 'Xataka', 'https://www.xataka.com/videojuegos/dlss-5-desato-polemica-convertir-videojuegos-peliculas-hemos-probado-nba-2k27-realidad-mucho-sutil'),
('oled-burnin', 'Monitores OLED y el mito del "Burn-In"', 'El "burn-in" o marcado permanente en monitores OLED ya no es un fallo inminente, sino un desgaste físico real de los píxeles que hoy se mitiga de forma muy efectiva, aunque persisten ciertos riesgos en usos extremos.', '/img/oled.jpg', ARRAY['Durante años, el temor al ''burn-in'' fue uno de los principales frenos para quienes consideraban un monitor OLED gamer. Este fenómeno ocurre cuando un elemento estático (como un HUD o una barra de tareas) permanece demasiado tiempo en pantalla y desgasta de forma desigual los píxeles.','Los fabricantes actuales incorporan mecanismos de protección como el desplazamiento sutil de píxeles, limitadores de brillo automático y ciclos de mantenimiento que se ejecutan cuando el monitor entra en reposo, reduciendo drásticamente el riesgo bajo un uso normal.','El riesgo real se mantiene en escenarios extremos: pantallas completas usadas muchas horas al día, en la misma composición estática, sin pausas. Para el uso mixto de un gamer promedio (juegos variados, oficina, streaming), el burn-in dejó de ser una amenaza inminente.']::text[], 'Xataka', 'https://www.xataka.com/seleccion/hablemos-quemados-teles-oled-2026-siguen-siendo-problema-quedo-pasado');